from taf.hw.optical_switch.devices.base import OpticalSwitch
from taf.hw.optical_switch.devices.clients.tcp_client import TCPClient


class TCPOpticalSwitch(OpticalSwitch):

    def __init__(
        self,
        host,
        port=None,
        timeout=10,
        buffer_size=128,
        decode="utf-8",
        retry=3,
        interval=1,
    ):

        super().__init__(host=host, port=port, timeout=timeout)

        self._buffer_size = buffer_size
        self._decode = decode
        self._timeout = timeout
        self._retry = retry
        self._interval = interval
        self._tcp_client = TCPClient(
            host=host,
            port=port,
            timeout=timeout,
            buffer_size=buffer_size,
            encoding=decode,
            interval=interval,
        )

    def teardown(self):
        """Teardown and disconnect if needed."""
        self._tcp_client.disconnect()
